                "RQ-19d7f5e27dcd4a1d9236315f6bf288e3",
                "RQ-b5ce45a545254d1a8aa205a5944535e3",
                "RQ-b0dfd40c17bb4789ab08cf31f920ecb9",
                "RQ-b2b58a9a58ac4834840be0bc238e275f"
              ],
              "source_block_ids": [
                "SB-8C80E96FC81CA641",
                "SB-3930A390340951B7",
                "SB-9E135AFD8D79ED3C",
                "SB-B84109DE92C147BA",
                "SB-A9833CF255BDF6C0",
                "SB-F7DB8CD5A9668EF4",
                "SB-5B889D232D13901F",
                "SB-83C0467B0FFB419F"
              ],
              "entry_condition": "Provision a separate synthetic scenario with its own newly empty durable J and fixed R. Retain J throughout that scenario, serialize calls and prevent process overlap. Confirm each process startup independently before dispatching a fresh-id business call.",
              "branches": [
                {
                  "kind": "failure",
                  "applicability": "applicable",
                  "rationale": "Event, observation, barrier and lifecycle failures remain latched across provisional progression, crashes, replacement processes and cleanup.",
                  "boundary_ids": [
                    "scenario-failure"
                  ]
                },
                {
                  "kind": "cancel",
                  "applicability": "applicable",
                  "rationale": "An empty-journal cancel establishes an immutable permanent decline, zero grants and one logical map return.",
                  "boundary_ids": [
                    "durable-cancellation"
                  ]
                },
                {
                  "kind": "return",
                  "applicability": "applicable",
                  "rationale": "The first durable decision supplies its single logical map return. Finalization automatically presents the journal-selected result.",
                  "boundary_ids": [
