                      "owner_revision": 1
                    },
                    {
                      "kind": "state",
                      "definition_id": "retained-scenario-audit",
                      "owner_plan_id": "PLAN-bed480ce3e404b2cbaf5514d80a7f941",
                      "owner_revision": 1
                    }
                  ],
                  "responsibility": "Deliver the documented exclusive-reward-jsonl version 1 profile, runtime bindings, HookArmed return path, hook boundaries and journal reader contract for shared controller/harness use before business dispatch.",
                  "result": "Independent startup confirmation gates dispatch using the selected shared profile."
                },
                {
                  "id": "rendered-result-to-observer",
                  "from": {
                    "flow_id": "FLOW-f78c671da6d04b7dbed7a6111d652007",
                    "node_id": "finalize"
                  },
                  "to": {
                    "flow_id": "FLOW-f78c671da6d04b7dbed7a6111d652007",
                    "node_id": "observe"
