                      "definition_id": "rendered-map-ui",
                      "owner_plan_id": "PLAN-bed480ce3e404b2cbaf5514d80a7f941",
                      "owner_revision": 1
                    }
                  ],
                  "responsibility": "Supply deterministic visible state indicators, OS capture recognition regions and full-journal observation integration.",
                  "result": "The harness independently compares actual rendered UI and every durable record with the reported completion and expected outcome."
                },
                {
                  "id": "retained-state-to-replacement",
                  "from": {
                    "flow_id": "FLOW-f78c671da6d04b7dbed7a6111d652007",
                    "node_id": "exit-audit"
                  },
                  "to": {
                    "flow_id": "FLOW-f78c671da6d04b7dbed7a6111d652007",
                    "node_id": "startup"
                  },
                  "owner": {
                    "kind": "command",
                    "definition_id": "harness-lifecycle-and-observation",
                    "owner_plan_id": "PLAN-bed480ce3e404b2cbaf5514d80a7f941",
                    "owner_revision": 1
                  },
                  "state_uses": [
                    {
                      "kind": "state",
                      "definition_id": "decision-journal",
                      "owner_plan_id": "PLAN-bed480ce3e404b2cbaf5514d80a7f941",
                      "owner_revision": 1
                    },
                    {
                      "kind": "state",
                      "definition_id": "retained-scenario-audit",
                      "owner_plan_id": "PLAN-bed480ce3e404b2cbaf5514d80a7f941",
                      "owner_revision": 1
                    }
                  ],
                  "responsibility": "After confirmed exit, EOF/drain and instance audit, preserve J, issued ids, counts and failures while creating fresh channels and a new owned instance association.",
                  "result": "A nonoverlapping replacement confirms initial Idle and unchanged complete J before ordinary fresh-id resume."
                }
              ],
              "state_owners": [
                {
                  "kind": "state",
                  "definition_id": "decision-journal",
                  "owner_plan_id": "PLAN-bed480ce3e404b2cbaf5514d80a7f941",
